#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){scanf("%d",&par[i]);ch[par[i]].push_back(i);}
    vector<bool>isLeaf(N+1,false);
    vector<int>leaves;
    for(int i=1;i<=N;i++)if(ch[i].empty()){isLeaf[i]=true;leaves.push_back(i);}
    int L=leaves.size();
    if(N<=3){
        printf("1\n%d",N);
        for(int i=1;i<=N;i++)printf(" %d",i);
        printf("\n");
        return 0;
    }
    vector<int>lf(N+1,N+1),rf(N+1,0);
    for(int v=N;v>=1;v--){
        if(isLeaf[v])lf[v]=rf[v]=v;
        for(int c:ch[v]){lf[v]=min(lf[v],lf[c]);rf[v]=max(rf[v],rf[c]);}
    }
    // Each node v returns an interval [entryBag, exitBag]
    // entryBag contains {v, par(v), lf[v]}, exitBag contains {v, par(v), rf[v]}
    vector<vector<int>>bags;
    vector<vector<int>>adj;
    auto addBag=[&](vector<int>b)->int{int id=bags.size();bags.push_back(b);adj.push_back({});return id;};
    auto addEdge=[&](int a,int b){if(a>=0&&b>=0){adj[a].push_back(b);adj[b].push_back(a);}};
    vector<int>entry(N+1,-1),exitt(N+1,-1);
    // Process bottom-up
    for(int v=N;v>=1;v--){
        int p=par[v];
        if(isLeaf[v]){
            int b=addBag(p?vector<int>{v,p}:vector<int>{v});
            entry[v]=exitt[v]=b;
        } else {
            int k=ch[v].size();
            int prev=-1;
            for(int i=0;i<k;i++){
                int c=ch[v][i];
                // Bag connecting to child c's entry
                int b1=addBag(p?vector<int>{v,p,lf[c]}:vector<int>{v,lf[c]});
                if(i==0)entry[v]=b1;
                if(prev>=0)addEdge(prev,b1);
                addEdge(b1,entry[c]);
                int b2=addBag(p?vector<int>{v,p,rf[c]}:vector<int>{v,rf[c]});
                addEdge(b1,b2); addEdge(b2,exitt[c]);
                if(i<k-1){
                    int b3=addBag(p?vector<int>{v,p,rf[c],lf[ch[v][i+1]]}:vector<int>{v,rf[c],lf[ch[v][i+1]]});
                    addEdge(b2,b3); prev=b3;
                } else { exitt[v]=b2; prev=b2; }
            }
        }
    }
    // Wrap-around ring edge: last leaf -> first leaf
    int b=addBag({1,leaves[0],leaves[L-1]});
    addEdge(b,entry[1]); addEdge(b,exitt[1]);
    int BN=bags.size();
    printf("%d\n",BN);
    for(int i=0;i<BN;i++){printf("%d",(int)bags[i].size());for(int x:bags[i])printf(" %d",x);printf("\n");}
    for(int i=0;i<BN;i++)for(int j:adj[i])if(j>i)printf("%d %d\n",i+1,j+1);
}
